Ext.define('ViewDashlet.view.ContextMenuViewController', {
    extend: 'Ext.app.ViewController',
    alias: 'controller.contextmenu',

    onMenuBeforeRender: function(component, eOpts) {
        var me = component,
            Translator = DashletHTML.controller.Translator,

            itemDrillBack = me.lookupReference('drillBack'),
            itemDrillForward = me.lookupReference('drillForward'),
            itemExport = me.lookupReference('export'),
            itemNavigate = me.lookupReference('navigate'),
            itemDrillGridHeader = me.lookupReference('drillGridHeader');

        itemDrillBack.setText(Translator.getMessage('ctx_drill_back'));
        itemDrillForward.setText(Translator.getMessage('ctx_drill_forward'));

        itemExport.setText(Translator.getMessage('menu_excel'));
        itemNavigate.setText(Translator.getMessage('menu_navigate'));

        itemDrillGridHeader.setText(Translator.getMessage('drillChild'));

    }

});
